using System;

namespace Model
{
    // BUSINESS LAYER: Model. One row of TabReserved.
    //
    //     RID           int      -> primary key, generated by the database
    //     UID           int      -> FK to TabUser
    //     ISBN          varchar  -> FK to TabBook
    //     ReservedDate  date
    public class Reserved
    {
        private int rId;
        private int uId;
        private string isbn;
        private DateTime reservedDate;

        // Not a column. ReservedLogic fills it from the book list so the reservations
        // report can show the title instead of only the ISBN.
        private string bookName;

        public int RID { get => rId; set => rId = value; }
        public int UID { get => uId; set => uId = value; }
        public string ISBN { get => isbn; set => isbn = value; }
        public DateTime ReservedDate { get => reservedDate; set => reservedDate = value; }
        public string BookName { get => bookName; set => bookName = value; }
    }
}